package com.cju.likelion.cardcollection.reward.controller;
import com.cju.likelion.cardcollection.common.api.ApiResponse; import com.cju.likelion.cardcollection.reward.dto.*; import com.cju.likelion.cardcollection.reward.service.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/rewards") public class RewardController {private final RewardQueryService service;private final RewardProgressService progress;public RewardController(RewardQueryService s,RewardProgressService p){service=s;progress=p;} @GetMapping("/progress") public ResponseEntity<ApiResponse<List<RewardProgressResponse>>> progress(Authentication a){return ResponseEntity.ok(new ApiResponse<>(progress.list(id(a))));} @GetMapping("/progress/{collectionId}") public ResponseEntity<ApiResponse<RewardCollectionDetailResponse>> progressDetail(Authentication a,@PathVariable UUID collectionId){return ResponseEntity.ok(new ApiResponse<>(progress.detail(id(a),collectionId)));} @GetMapping("/my") public ResponseEntity<ApiResponse<List<UserRewardResponse>>> my(Authentication a){return ResponseEntity.ok(new ApiResponse<>(service.my(id(a))));} @PostMapping("/{id}/claim") public ResponseEntity<ApiResponse<UserRewardResponse>> claim(Authentication a,@PathVariable UUID id){return ResponseEntity.ok(new ApiResponse<>(service.claim(id(a),id)));} private UUID id(Authentication a){return UUID.fromString(a.getName());}}
